'use client'; import { useCallback, useState } from 'react'; export type VendorFeedback = { type: 'success' | 'error'; message: string } | null; export function useVendorFeedback() { const [feedback, setFeedback] = useState<VendorFeedback>(null); const showSuccess = useCallback((message: string) => { setFeedback({ type: 'success', message }); window.setTimeout(() => setFeedback(null), 4500); }, []); const showError = useCallback((message: string) => { setFeedback({ type: 'error', message }); window.setTimeout(() => setFeedback(null), 4500); }, []); const alertError = useCallback((message: string) => { window.alert(`Error: ${message}`); }, []); const alertSuccess = useCallback((message: string) => { window.alert(message); }, []); return { feedback, showSuccess, showError, alertError, alertSuccess };
} export function VendorFeedbackBanner({ feedback }: { feedback: VendorFeedback }) { if (!feedback) return null; return ( <div role="status" className={`rounded-lg border px-4 py-3 text-sm font-medium ${ feedback.type === 'success' ? 'border-emerald-300 bg-emerald-50 text-emerald-900' : 'border-red-300 bg-red-50 text-red-800' }`} > {feedback.message} </div> );
}
